    try {
        if (cursor.moveToFirst()) {
            val titleIndex = cursor.getColumnIndexOrThrow(TaskContract.TaskEntry.COLUMN_NAME_TITLE)
            do {
                val text = cursor.getString(titleIndex)
                if (text != null) tasks.add(text)
            } while (cursor.moveToNext())
        }
    } finally {
        cursor.close()
    }
    return tasks
}

